def spread(start, target, n=6):
    """Due dates for the steps, evenly from start to the target date (the last step on the target)."""
    days = max((target - start).days, n)
    return [start + dt.timedelta(days=round(days * (i + 1) / n)) for i in range(n)]


def link(apps, schema_editor):
    """Existing accreditations cover the accredited courses of their body; projects get due dates."""
    Accreditation = apps.get_model("assurance", "Accreditation")
    Project = apps.get_model("assurance", "AccreditationProject")
    Course = apps.get_model("courses", "Course")
    for a in Accreditation.objects.all():
        a.courses.set(Course.objects.filter(is_accredited=True, accreditation_body_id=a.body_id))
    for p in Project.objects.all():
        start = p.created_at.date() if p.created_at else p.target_date - dt.timedelta(days=180)
        p.step_due = spread(start, p.target_date)
        p.step_done = [start] * p.step_index + [None] * (6 - p.step_index)
        p.step_notes = [""] * 6
        if "game" in p.scope.lower():
            p.courses.set(Course.objects.filter(code="TRN-GAME"))
        if p.scope.lower().startswith("renewal"):
            held = Accreditation.objects.filter(body_id=p.body_id).order_by("-expires_on").first()
            if held:
                p.renews = held
                p.courses.set(held.courses.all())
        p.save()


